Here is the source code:
<source_code>
import java.io.*;
import java.util.*;

public class E {

	static long mod = 998244353;
	public static void main(String[] args) {
		FastScanner sc = new FastScanner();
		long n = sc.nextInt();
		long m = sc.nextInt();
		long L = sc.nextInt();
		long R = sc.nextInt();
		if(n % 2 == 1 && m % 2 == 1) {
			System.out.println(pow((R-L+1) % mod, n*m));
		}
		else {
			if((R - L + 1) % 2 == 0) {
				long allbutone = pow((R-L+1) % mod, n*m-1);
				long res = allbutone * ((R-L+1)/2) % mod;
				System.out.println(res);
			}
			else { //fun case
				Matrix id = new Matrix(1,0,0,1);
				long k = (R - L + 1) / 2;
				Matrix mat = new Matrix(k, k+1, k+1, k);
				Matrix res = mat.pow(n*m);
				System.out.println(res.mat[0][0]);
			}
		}
	}
	static class Matrix{
		long[][] mat = new long[2][2];
		public Matrix(long a, long b, long c, long d) {
			mat[0][0] = a;
			mat[0][1] = b;
			mat[1][0] = c;
			mat[1][1] = d;
		}
		public Matrix(long[][] mat) {
			this.mat = mat;
		}
		public Matrix pow(long x) {
			Matrix res = new Matrix(1, 0, 0, 1);
			Matrix a = new Matrix(mat);
			while(x > 0) {
				if(x % 2 == 1) {
					res = res.mult(a);
				}
				a = a.mult(a);
				x /= 2;
			}
			return res;
		}
		public Matrix mult(Matrix m) {
			long[][] rmat = new long[2][2];
			for(int i = 0; i < 2; i++) {
				for(int j = 0; j < 2; j++) {
					for(int k = 0; k < 2; k++) {
						rmat[i][j] += mat[i][k] * m.mat[k][j];
						rmat[i][j] %= mod;
					}
				}
			}
			return new Matrix(rmat);
		}
		public String toString() {
			return 
			mat[0][0]+" "+mat[0][1]+"\n"+
			mat[1][0]+" "+mat[1][1];
		}
	}

	static long pow(long a, long b) {
		long res = 1;
		while(b > 0) {
			if(b % 2 == 1) {
				res = (res * a) % mod;
			}
			a = (a * a) % mod;
			b /= 2;
		}
		return res;
	}

	static class FastScanner {
		public BufferedReader reader;
		public StringTokenizer tokenizer;
		public FastScanner() {
			reader = new BufferedReader(new InputStreamReader(System.in), 32768);
			tokenizer = null;
		}
		public String next() {
			while (tokenizer == null || !tokenizer.hasMoreTokens()) {
				try {
					tokenizer = new StringTokenizer(reader.readLine());
				} catch (IOException e) {
					throw new RuntimeException(e);
				}
			}
			return tokenizer.nextToken();
		}
		public int nextInt() {
			return Integer.parseInt(next());
		}
		public long nextLong() {
			return Long.parseLong(next());
		}
		public double nextDouble() {
			return Double.parseDouble(next());
		}
		public String nextLine() {
			try {
				return reader.readLine();
			} catch(IOException e) {
				throw new RuntimeException(e);
			}
		}
	}

}

